  "description-25": ".lp-pd .ql-container .ql-editor{padding:40px 20px;background:#e8fdda}.lp-pd div:has(>img){height:unset !important}.lp-pd img{width:100% !important;height:auto !important;margin:0 !important}.lp-pd .advanced-text .ql-editor,.lp-pd .advanced-text .ql-editor>div{display:flex;flex-direction:column;justify-content:center;gap:24px}.lp-pd ul,.lp-pd ul li{list-style:none !important;margin:0 !important;padding:0 !important;font-size:16px;color:var(--pd-body,#152c31);font-weight:700}.lp-pd li::before{display:none !important}.lp-pd h1{color:var(--pd-title,#4d4d4d);font-size:var(--pd-title-size,20px) !important;font-style:normal;font-weight:400;line-height:1.5}.lp-pd h2{color:var(--pd-body,#262626);font-size:16px !important;font-style:normal;font-weight:400}.lp-pd h3{color:var(--pd-title,#1d1d1d);font-size:var(--pd-title-size,40px) !important;font-style:normal;font-weight:500;line-height:1.2}@media(min-width:1200px){.lp-pd .container{width:1200px !important}}@media(max-width:992px){.lp-pd h1{font-size:var(--pd-title-size,16px) !important}.lp-pd h2{font-size:16px !important}.lp-pd h3{font-size:var(--pd-title-size,28px) !important}}.lp-pd .advanced-text>div:first-child{height:max-content!important}.lp-pd li{width:100%;margin:0 20px;padding:0 !important}"
